const D = { energy: .6, scale: 1, hue: 28, speed: 1, density: .55, blades: 5, wind: .7, blur: .7, x: .5, y: .46, style: 'industrial', seed: 0, act: 'idle' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const cx = P.x * width, cy = P.y * height;
const R = u * 0.30 * P.scale;                 // fan radius
const nB = Math.max(2, Math.min(9, Math.round(P.blades)));
const style = P.style;
const wire = style === 'blueprint';
const riso = style === 'riso';
const thermal = style === 'thermal';
const noir = style === 'noir';

// smoothed audio
S.bass = (S.bass || 0) * .82 + (A.bass || 0) * .18;
S.tre = (S.tre || 0) * .8 + (A.treble || 0) * .2;
S.rms = (S.rms || 0) * .85 + (A.rms || 0) * .15;

// ---- dramaturgy: section-indexed spin program ----
const ACTS = {
  idle:  [.35,.5,.7,.55,.4,.8,1,.5],
  surge: [.2,.6,1,.7,.3,.9,1,.8],
  windmill:[.6,.65,.7,.75,.7,.8,.85,.9] };
const arc = (ACTS[P.act] || ACTS.idle)[((K.section % 8) + 8) % 8];
const drive = P.energy * (.45 + .75 * arc) + S.bass * .5;

// continuous rotation (REAL time -> never re-phases at 8s)
const spinRate = (0.9 + 5.5 * drive) * P.speed;       // rad/s
const ang = K.t * spinRate;
const gust = 1 + S.bass * .8 + K.pulse * .25 * P.energy;

// housing vibration
const vib = (.5 + 2.6 * drive) * (u * .003);
const shx = Math.sin(K.t * 21.3 + fr(3) * 6) * vib + Math.sin(K.t * 33.7) * vib * .4;
const shy = Math.cos(K.t * 18.9 + fr(7) * 6) * vib * .8;

// ---------- palette ----------
const H = P.hue;
function P3(role) {
  if (wire) return { plate:[210,55,90], hi:[205,20,100], lo:[212,60,64], cage:[205,35,100], blade:[200,45,100], bhi:[195,25,100], hub:[195,55,95], hot:[190,60,100], bolt:[205,30,100], grime:[210,70,50] }[role];
  if (riso) { const b=[(H+152)%360,72,86]; return { plate:[H,78,88], hi:[H,55,100], lo:[H,86,66], cage:b, blade:[H,80,90], bhi:b, hub:b, hot:[H,70,100], bolt:b, grime:[H,88,58] }[role]; }
  if (thermal) return { plate:[248,55,30], hi:[210,40,60], lo:[255,70,16], cage:[228,50,44], blade:[18,90,92], bhi:[45,85,100], hub:[52,30,100], hot:[58,20,100], bolt:[210,30,70], grime:[262,60,20] }[role];
  if (noir) return { plate:[H,10,14], hi:[H,4,96], lo:[H,14,5], cage:[H,8,20], blade:[H,7,26], bhi:[H,3,92], hub:[H,12,30], hot:[H,20,80], bolt:[H,6,44], grime:[H,15,8] }[role];
  // industrial (default): raking-lit desaturated steel
  return { plate:[H,13,42], hi:[H,7,72], lo:[H,20,17], cage:[H,10,28], blade:[H,9,52], bhi:[H,5,84], hub:[H,32,46], hot:[(H+10)%360,60,70], bolt:[H,8,60], grime:[H,44,22] }[role];
}
const cf = (r, a) => { const c = P3(r); return color(c[0], c[1], c[2], a == null ? 100 : a); };

// ---------- static housing buffer ----------
const key = [Math.round(width), Math.round(height), Math.round(P.scale*100), P.seed, style, Math.round(H), nB, Math.round(P.density*20)].join('|');
if (!S.buf || S.bufKey !== key) {
  if (S.buf) S.buf.remove();
  const Dm = Math.ceil(R * 2.55);
  const g = createGraphics(Dm, Dm);
  g.colorMode(HSB, 360, 100, 100, 100);
  g.push(); g.translate(Dm / 2, Dm / 2);
  const C = (r, a) => { const c = P3(r); return g.color(c[0], c[1], c[2], a == null ? 100 : a); };
  const rOut = R, rIn = R * .9, rBrk = R * 1.14;

  // mounting bracket / pole (behind)
  if (!wire) {
    g.noStroke();
    g.fill(C('grime')); g.rect(-R*.10, R*.86, R*.20, R*.7, R*.02);
    g.fill(C('lo')); g.rect(-R*.13, R*.82, R*.26, R*.16, R*.03);
    g.fill(C('plate')); g.rect(-R*.09, R*.84, R*.18, R*.66, R*.02);
    g.fill(C('hi', 40)); g.rect(-R*.09, R*.84, R*.05, R*.66, R*.02);
  } else {
    g.noFill(); g.stroke(C('plate')); g.strokeWeight(Math.max(1, R*.008));
    g.rect(-R*.10, R*.84, R*.20, R*.7);
  }

  // outer safety-cage rim (steel torus)
  if (!wire) {
    g.noStroke();
    g.fill(C('lo')); g.ellipse(0, R*.03, rBrk*2, rBrk*2);           // drop shadow
    g.fill(C('plate')); g.ellipse(0, 0, rBrk*2, rBrk*2);
    g.fill(C('grime', 55)); g.ellipse(0, 0, rBrk*2, rBrk*2);
    // erase inner (housing well)
    g.erase(); g.ellipse(0, 0, rOut*2, rOut*2); g.noErase();
    // raking highlight on upper-left of rim
    g.noFill(); g.strokeWeight(rBrk - rOut);
    g.stroke(C('hi', noir ? 100 : 55)); g.arc(0, 0, rBrk + rOut, rBrk + rOut, Math.PI*1.05, Math.PI*1.6);
    g.stroke(C('lo', 70)); g.arc(0, 0, rBrk + rOut, rBrk + rOut, Math.PI*.1, Math.PI*.55);
  } else {
    g.noFill(); g.stroke(C('plate')); g.strokeWeight(Math.max(1.4, R*.012));
    g.ellipse(0, 0, rBrk*2, rBrk*2); g.ellipse(0, 0, rOut*2, rOut*2);
  }

  // grille: concentric rings
  g.noFill();
  const rings = 3 + Math.round(P.density * 3);
  for (let r = 1; r <= rings; r++) {
    const rr = rIn * (r / (rings + .4));
    g.strokeWeight(Math.max(1, R * (wire ? .006 : .012)));
    g.stroke(C('cage', wire ? 100 : 78));
    g.ellipse(0, 0, rr * 2, rr * 2);
    if (!wire) { g.stroke(C('hi', 24)); g.strokeWeight(Math.max(.8, R*.004)); g.ellipse(-R*.01, -R*.01, rr*2, rr*2); }
  }
  // grille: radial spokes
  const spokes = 8 + Math.round(P.density * 8);
  for (let i = 0; i < spokes; i++) {
    const a = (i / spokes) * Math.PI * 2 + fr(i) * .04;
    g.strokeWeight(Math.max(1, R * (wire ? .005 : .01)));
    g.stroke(C('cage', wire ? 90 : 66));
    g.line(Math.cos(a) * rIn * .12, Math.sin(a) * rIn * .12, Math.cos(a) * rIn, Math.sin(a) * rIn);
  }
  // bolts around rim
  if (!wire) {
    const nBolt = 8 + Math.round(P.density * 8);
    g.noStroke();
    for (let i = 0; i < nBolt; i++) {
      const a = (i / nBolt) * Math.PI * 2;
      const bx = Math.cos(a) * (rOut + rBrk) / 2, by = Math.sin(a) * (rOut + rBrk) / 2;
      g.fill(C('lo', 80)); g.circle(bx + R*.006, by + R*.006, R*.05);
      g.fill(C('bolt')); g.circle(bx, by, R*.045);
      g.fill(C('hi', 60)); g.circle(bx - R*.012, by - R*.012, R*.018);
    }
  }
  // blueprint dimension ticks
  if (wire) {
    g.stroke(C('blade', 70)); g.strokeWeight(1);
    g.line(0, -rBrk*1.06, 0, -rBrk*1.14); g.line(-R*.04, -rBrk*1.1, R*.04, -rBrk*1.1);
    g.line(-rBrk*1.06, 0, -rBrk*1.14, 0);
    g.noFill(); g.ellipse(0, 0, R*.5, R*.5);
  }
  g.pop();
  S.buf = g; S.bufKey = key; S.Dm = Dm;
}

// ================= LIVE RENDER =================
push();
translate(cx + shx, cy + shy);

// ---- rotating blades with motion-blur trailing copies ----
const trail = Math.max(1, Math.min(10, Math.round(1 + drive * 7 * (.4 + P.blur))));   // blur depth grows w/ speed (capped)
const trailStep = spinRate * 0.016 * (.6 + P.blur);                     // radians between ghosts
const rBl = R * .82, rHub = R * .2;
noStroke();
for (let t = trail - 1; t >= 0; t--) {
  const a0 = ang - t * trailStep;
  const aFade = (1 - t / trail);
  const al = wire ? 0 : (thermal ? 70 : 66) * aFade / (1 + trail * .18);
  for (let b = 0; b < nB; b++) {
    const a = a0 + (b / nB) * Math.PI * 2;
    push(); rotate(a);
    // one blade: leaf shape from hub to tip
    const bw = R * (.26 + .10 * (P.blur));
    if (wire) {
      stroke(cf('blade', 90)); strokeWeight(Math.max(1, R*.006)); noFill();
      beginShape();
      vertex(rHub*.4, -bw*.2); bezierVertex(rBl*.5, -bw*.7, rBl*.95, -bw*.2, rBl, 0);
      bezierVertex(rBl*.95, bw*.2, rBl*.5, bw*.7, rHub*.4, bw*.2);
      endShape(CLOSE);
      pop(); continue;
    }
    // pitch shading: leading edge bright, trailing dark
    fill(cf(b === 0 && !thermal ? 'hot' : 'blade', al));
    beginShape();
    vertex(rHub*.4, -bw*.15);
    bezierVertex(rBl*.5, -bw*.85, rBl*.9, -bw*.35, rBl, -bw*.05);
    bezierVertex(rBl*1.0, bw*.05, rBl*.6, bw*.5, rHub*.4, bw*.15);
    endShape(CLOSE);
    if (t === 0) { // crisp leading highlight only on front copy
      fill(cf('bhi', thermal ? 80 : 60));
      beginShape();
      vertex(rHub*.5, -bw*.1);
      bezierVertex(rBl*.5, -bw*.8, rBl*.88, -bw*.32, rBl*.98, -bw*.05);
      bezierVertex(rBl*.9, -bw*.02, rBl*.5, -bw*.35, rHub*.5, -bw*.02);
      endShape(CLOSE);
    }
    pop();
  }
}

// ---- hub with sweeping specular glint ----
push();
if (!wire) {
  noStroke();
  fill(cf('hub')); circle(0, 0, rHub * 2);
  fill(cf('grime', 40)); circle(0, 0, rHub * 2);
  // rotating glint
  const gA = ang * .5;
  fill(cf('hot', 70 + 30 * K.swell));
  ellipse(Math.cos(gA) * rHub * .4, Math.sin(gA) * rHub * .4, rHub * .8, rHub * .5);
  fill(cf('bhi', 65)); circle(-rHub*.3, -rHub*.3, rHub*.5);
  fill(cf('lo', 90)); circle(0, 0, rHub * .55);         // center cap bolt
  fill(cf('bolt')); circle(0, 0, rHub * .32);
} else {
  stroke(cf('hub')); strokeWeight(Math.max(1.4, R*.01)); noFill();
  circle(0, 0, rHub * 2); circle(0, 0, rHub * .6);
  line(-rHub, 0, rHub, 0); line(0, -rHub, 0, rHub);
}
pop();

// ---- static housing (cage + rim + bracket) on top ----
image(S.buf, -S.Dm / 2, -S.Dm / 2);

// thermal center hot bloom
if (thermal) {
  blendMode(ADD); noStroke();
  for (let r = 3; r >= 1; r--) { fill(52, 30, 100, 6 + 5 * K.swell); circle(0, 0, rHub * r * 1.3); }
  blendMode(BLEND);
}
pop(); // end fan

// =============== WIND STREAKS (downwind, blowing right) ===============
// continuous outward travel via K.t -> guaranteed motion floor, sweeps the frame
const windOn = P.wind * (.5 + drive) * gust;
const nW = Math.round((6 + P.density * 26) * Math.min(1, .3 + windOn));
const reach = width * (.5 + .5 * Math.min(1.4, windOn));
push();
translate(cx + shx, cy + shy);
if (!wire) blendMode(ADD);
noFill();
for (let i = 0; i < nW; i++) {
  const seed = fr(i * 2 + 11);
  const spread = (seed - .5) * R * 2.3;                 // vertical launch offset
  const spd = (.10 + seed * .16) * (1 + drive);          // travel speed (frac/s)
  const ph = (K.t * spd + seed) % 1;                     // 0..1 progress, loops
  const startX = R * .95;
  const px = startX + ph * reach;
  const droop = ph * ph * R * .5 * (1 - windOn * .3);    // gravity sag
  const turb = Math.sin(K.t * 3 + seed * 20 + px * .01) * R * .12 * (.4 + windOn);
  const py = spread * (1 + ph * .6) + droop + turb;
  const life = Math.sin(ph * Math.PI);                   // fade in/out along path
  const len = (R * .35 + reach * .12) * (.5 + windOn);
  const wcol = P3('wind');
  const al = life * (wire ? 55 : (34 + 30 * windOn));
  strokeWeight(Math.max(1, R * .012 * (.6 + life)));
  stroke(wcol[0], wcol[1], wcol[2], al);
  // speed-line as short curved dash
  const x2 = px - len, y2 = py - turb * .3 - Math.sin(K.t*3+seed*20)*R*.02;
  line(px, py, x2, y2);
  if (windOn > .5 && i % 3 === 0) { // secondary echo streak (for other assets to riff on)
    stroke(wcol[0], Math.max(0, wcol[1]-15), Math.min(100, wcol[2]+8), al * .5);
    line(px, py + R*.05, px - len*.7, y2 + R*.05);
  }
}
blendMode(BLEND);
pop();

drawingContext.shadowBlur = 0;
blendMode(BLEND);
